"""Build the completion report from accepted outputs, never from success labels alone."""
from pathlib import Path
import json,csv,io,hashlib
R=Path(__file__).resolve().parents[1];O=R/'outputs/remediation_v1';D=R/'docs'
def main():
    a=json.loads((O/'analysis.json').read_text());i=json.loads((O/'integrity_recheck.json').read_text());s=json.loads((O/'secondary_summary.json').read_text());m=json.loads((R/'outputs/mcu_deadline_v1/analysis.json').read_text());diag=json.loads((O/'archive_diagnostics/summary.json').read_text())
    publication=R/'publication/array';visual=json.loads((publication/'remediation_visual_review.json').read_text());document=json.loads((publication/'remediation_manuscript_audit.json').read_text())
    if visual['status']!='passed_page_by_page_review' or document['status']!='passed' or visual['pdf_sha256']!=hashlib.sha256((publication/'Array_Manuscript.pdf').read_bytes()).hexdigest() or document['final_docx_sha256']!=hashlib.sha256((publication/'Array_Manuscript.docx').read_bytes()).hexdigest():raise ValueError('Stale publication evidence')
    assert a['runs']==i['cases']==1440 and i['status']=='passed_complete_archive_integrity'
    rows=[
      ('A: causal attribution','RESOLVED','Four matched arms share ACK, expiry, positive-credit and late-positive semantics; negative update and proof traffic cross independently. Separate active reference retained.','experiments/remediation_v1; outputs/remediation_v1/analysis.json','Conditional effects within this fixture family; not attribution of the complete historical ns-3 gain.'),
      ('B: identity / ordering','RESOLVED','Both physical attackers, two relay-ID permutations, 12 perturbed geometries, three retained checkpoints and benign controls executed.','experiments/remediation_v1/protocol.json; outputs/remediation_v1/integrity_recheck.json','Geometry/checkpoint/onset/channel are balanced block factors, not a fully crossed population study.'),
      ('C: censored-frozen equality','RESOLVED',f"{diag['matched_decisions']} matched decisions: {diag['risk_different_decisions']} risk differences, no ordering or action disagreement. {diag['offline_action_changes']}/{diag['offline_interventions']} offline interventions change action.",'outputs/remediation_v1/archive_diagnostics; outputs/remediation_v1/feedback_trajectories.csv.gz','Offline sensitivity does not establish closed-loop radio gain or invariance to every risk input.'),
      ('D: failure characterization','RESOLVED','Frozen onset/channel/geometry/checkpoint design and sustained-recovery/censoring metrics completed.','outputs/remediation_v1/secondary_summary.json; outputs/remediation_v1/exposure_summary.json; outputs/remediation_v1/secondary_run_diagnostics.json','No universal threshold; narrow fixture family and conditional latency summaries.'),
      ('Transfer scope / onset threshold','SCIENTIFIC LIMITATION','The shared four-node graph, 38 m progress normalization, clipped source progress, two onsets and three retained policies support conditional transfer findings.','outputs/remediation_v1/design_geometry_audit.json; experiments/remediation_v1/protocol.json','No universal threshold or broad network-scale claim. Wider independently varied graphs and fully crossed warm-up/onset/checkpoint fixtures need a new frozen study if that claim is pursued.'),
      ('E: loss versus lateness','RESOLVED','Benign delayed censored critical packets: 7 lost, 563 late, 30 timely of 600. Sink and source latency endpoints remain separate.','outputs/remediation_v1/archive_diagnostics; outputs/mcu_deadline_v1/stage_profile.json','Injected Cooja delays are not a serial CPU model or measured timing.'),
      ('E: original signed deadline','SCIENTIFIC LIMITATION',f"Compiler-only O3 still misses {sum(x['signed_deadline_misses'] for x in m['rows'])}/200; 200 packets and signed receipts delivered.",'outputs/mcu_deadline_v1','A further endpoint-preserving crypto/execution redesign and separately frozen evaluation are required; no pass claimed.'),
      ('F: security assumptions','RESOLVED','Implementation-wise key/evidence/ACK/session/provisioning matrix; unsupported identity/ACK/processing/credit mutation checks.','docs/SECURITY_EVIDENCE_MATRIX.md; tests/test_remediation*','Public fixture validation supplies no secrecy against fixture-key holders or runtime Byzantine truth guarantee.'),
      ('G: statistical analysis','RESOLVED','12-block paired inference; six primary Holm contrasts; separate secondary families; pointwise bootstrap intervals and explicit symmetric sign-flip assumption.','experiments/remediation_v1/protocol.json; outputs/remediation_v1/analysis.json','No nonsignificance-as-equivalence claim or invented deployment margin; no packet pseudoreplication.'),
      ('H: physical RF and energy','BLOCKED BY EXTERNAL ACCESS OR HUMAN CONFIRMATION','No compatible physical boards/instruments accessible; linked Mac offline at this check.','publication/array/external_validation_access_check.json','Provide compatible boards plus calibrated RF/current equipment; freeze protocol, acquire raw calibrated traces.'),
      ('H: production security','IMPLEMENTED BUT UNVALIDATED','Emulated key/session negative controls exist; protected storage, authenticated provisioning, firmware authenticity and reset-safe device sessions lack board evidence.','hardware/cc2538_live; docs/SECURITY_EVIDENCE_MATRIX.md','Board-specific port, secure provisioning/boot/storage tests and reset/power-loss captures required.'),
      ('H: author approval','BLOCKED BY EXTERNAL ACCESS OR HUMAN CONFIRMATION','Exact-version requests and approval register prepared; not sent; all final approval fields remain null.','publication/array/Coauthor_review_request_*; Approval_evidence_register_TEMPLATE.json','Actual authors must review the pinned paper and supply consent, roles, overlap and declarations.'),
      ('H: authenticated submission','BLOCKED BY EXTERNAL ACCESS OR HUMAN CONFIRMATION','Official guide returned 403 and browser homepage unavailable; authenticated requirements and assembled portal PDF unchecked.','publication/array/external_validation_access_check.json','Accessible official guide and authorized authenticated portal session; actual declarations require author confirmation.'),
      ('I: manuscript and exhibits','RESOLVED','Completed evidence integrated; old 11 tables, 12 images and 10 native equations preserved. Two data-derived figures and six-contrast Table 12 added.','publication/array; remediation_manuscript_audit.json','Array-specific final portal compliance and author approval remain separate gates.'),
      ('J: reproducibility / publication','RESOLVED','Frozen source, raw outputs, analyses, environments, regression records, durable releases and hashes provided.','docs/REMEDIATION_REPRODUCTION.md; FILE_MANIFEST.json','A published research package is not a submitted or accepted paper.'),
    ]
    f=io.StringIO();w=csv.writer(f);w.writerow(['Concern','Status','Evidence-backed outcome','Evidence path','Limit / next necessary action']);w.writerows(rows);(D/'REMEDIATION_CONCERN_MATRIX.csv').write_text(f.getvalue())
    text=['# Evidence-based remediation completion report','', 'Starting commit: `f9bf3c9382c73cee2f21fffa94e07f1a0affe415`. New mechanisms and experiments reside in versioned remediation directories; original experiments and failures remain retained.','',f"The separate Cooja study completes {a['runs']:,} cases over twelve geometry blocks. Archive integrity and all per-case audits pass. Its questions were motivated by historical outcomes, and its new analysis was frozen before new runs. No historical statistical family is pooled or overwritten.",'','## Concern-to-evidence matrix','', '| Concern | Status | Verified outcome | Limit / next action |','|---|---|---|---|']
    for concern,status,outcome,path,limit in rows:text.append('| '+ ' | '.join([concern,status,outcome+' Evidence: `'+path+'`.',limit])+' |')
    text+=['','## New primary effects','', '| Timing | Contrast | Effect (pp) | Pointwise 95% interval (pp) | Holm p |','|---|---|---:|---|---:|']
    for x in a['contrasts']:
        if x['endpoint']=='post_delivery':text.append(f"| {x['timing']} | {x['contrast']} | {100*x['mean_difference']:+.3f} | [{100*x['ci95'][0]:+.3f}, {100*x['ci95'][1]:+.3f}] | {x['p_holm']:.6g} |")
    text+=['','Timing 0 means no added compute delay; timing 1 uses illustrative overlapping scheduled delays. Intervals are pointwise and the six p-values share the prespecified Holm family. Sign flips require symmetric block effects, not assumed randomized treatment assignment. These results supply neither equivalence nor a universal operating boundary.','', '## Remaining full-validation gate','', 'The original signed deadline, physical measurement, production security, actual author approval and authenticated submission are not complete. No deadline was lengthened and the fast private-MAC endpoint does not satisfy the original signature requirement. See the matrix for the exact evidence and next action. No messages were sent and no submission was made.']
    text+=['','## Descriptive control supplement','','Benign means and checkpoint/onset/channel-stratified block effects are available in publication/array/Remediation_Control_Supplement.md and outputs/remediation_v1/control_and_factor_summary.json. These exploratory post-outcome aggregations add no tests, tuning or exclusions; the primary analysis is unchanged.']
    for category in ['RESOLVED','IMPLEMENTED BUT UNVALIDATED','SCIENTIFIC LIMITATION','BLOCKED BY EXTERNAL ACCESS OR HUMAN CONFIRMATION']:
        text+=['','## '+category,'']
        for concern,status,outcome,path,limit in rows:
            if status==category:text.append('- **'+concern+'**: '+outcome+' '+limit)
    (D/'REMEDIATION_COMPLETION_REPORT.md').write_text('\n'.join(text)+'\n')
    (O/'completion_status.json').write_text(json.dumps({'research_remediation_executed':True,'new_runs':1440,'archive_integrity':i,'original_signed_deadline_complete':False,'physical_validation':False,'production_security_validated':False,'coauthor_approvals_obtained':False,'authenticated_submission_checked':False,'full_validation_complete':False},indent=2)+'\n')
if __name__=='__main__':main()
